"""Labyrinthe des reliques (0.21) : verrou, démarrage et relique de départ (vrais clics), carte (cases accessibles), combats
(2 ennemis, 3 pour élites et gardiens), PV conservés entre les combats, fuite, effets des reliques, mystères, campement,
marchand, changement d'acte, victoire finale (récompenses, marques, profondeur débloquée), défaite, abandon, sauvegarde,
boutique des marques, codex, mise en page PC."""
import asyncio,pathlib,sys
from playwright.async_api import async_playwright
GAME=(pathlib.Path(__file__).resolve().parent.parent/'game'/'index.html').as_uri()
FAILS=[]
def check(name,cond,info=''):
    print(('OK   ' if cond else 'FAIL ')+name+(' '+str(info) if (info!='' and not cond) else ''))
    if not cond:FAILS.append(name)
SETUP='S.team=["rex","giga","raptor"].map((t,i)=>({id:i+1,type:t,level:30,xp:0}));S.nextId=20;S.stage=40;S.level=10;S.items=[];S.tut={off:true,seen:{}};S.maze=null;ens();save();render()'
FORCE='''(t)=>{const r=S.maze.run;r.pend=null;r.cur={r:Math.max(0,r.pos.r),c:Math.max(0,r.pos.c),t};fight=null;mzFight();return !!fight&&fight.o.mode==="maze"}'''
WIN='''()=>{let g=0;while(fight&&!fight.over&&g++<20){const e=fight.enemies[fight.wave];e.hp=1;e.sh=0;tapOrb(0)}return fight.over}'''
