        await fresh('["trophee"]','e');a=await ev('atkOf(0)');a0=await ev('(()=>{const s=fight.mzSt;fight.mzSt={...s,big:0};const v=atkOf(0);fight.mzSt=s;return v})()')
        check('Trophée : +25 % contre une élite',await ev('fight.wave')==0 or True)
